Glinka","points":300},{"rank":199,"name":"Oliver Crawford","points":300},{"rank":200,"name":"Sascha Gueymard Wayenburg","points":297}]$frozen_top200$::jsonb)
 AS x(rank integer,name text,points integer)
),
candidates AS MATERIALIZED (
 SELECT p.id,p.name,p.game_generated,p.data_source,p.ranking,p.points,p.game_world_rank,
  lower(regexp_replace(extensions.unaccent(p.name),'[^a-zA-Z0-9]+','','g')) normal_name
 FROM public.players p WHERE p.career_status='active'
), scored AS (
 SELECT f.rank,f.name frozen_name,f.points frozen_points,p.id,p.name actual_name,p.data_source,p.game_generated,p.ranking,p.points,p.game_world_rank,
 row_number() over(partition by f.rank order by
  CASE WHEN p.data_source='ISOLATED-ATP-2025-12-01-CC-BY-NC-SA-4.0' THEN 0
       WHEN p.game_generated=false THEN 1 ELSE 2 END,
  p.id NULLS LAST) priority
 FROM frozen f LEFT JOIN candidates p
 ON p.normal_name=lower(regexp_replace(extensions.unaccent(f.name),'[^a-zA-Z0-9]+','','g'))
), selected AS (SELECT * FROM scored WHERE priority=1), counts AS (
 SELECT count(*) total_top200,
 count(*) FILTER(WHERE data_source='ISOLATED-ATP-2025-12-01-CC-BY-NC-SA-4.0') direct_atp_profile_match,
 count(*) FILTER(WHERE id IS NOT NULL AND data_source<>'ISOLATED-ATP-2025-12-01-CC-BY-NC-SA-4.0' AND game_generated=false) name_only_nonimported,
 count(*) FILTER(WHERE id IS NOT NULL AND game_generated=true) generated_homonym_risk,
 count(*) FILTER(WHERE id IS NULL) no_name_match,
 count(*) FILTER(WHERE data_source='ISOLATED-ATP-2025-12-01-CC-BY-NC-SA-4.0' AND (ranking<>rank OR points<>frozen_points)) imported_source_drift,
 count(*) FILTER(WHERE id IS NOT NULL AND game_world_rank<>rank) in_game_rank_mismatch
 FROM selected
), provenance AS (
 SELECT (SELECT count(*) FROM public.atp_defending_points_ledger WHERE source_season=2025 AND rank_category<>'Reconciliation') per_event_entries,
 (SELECT count(*) FROM public.atp_defending_points_ledger WHERE rank_category='Reconciliation') synthetic_reconciliation_rows
)
SELECT pg_catalog.jsonb_build_object(
 'as_of','2025-12-01','reference_source','court-boss/data/atp-singles-2025-12-01.json',
 'total_top200',c.total_top200,'direct_atp_profile_match',c.direct_atp_profile_match,
 'name_only_nonimported',c.name_only_nonimported,'generated_homonym_risk',c.generated_homonym_risk,
 'no_name_match',c.no_name_match,'imported_source_drift',c.imported_source_drift,
 'in_game_rank_mismatch',c.in_game_rank_mismatch,
 'missing_reference_names',(SELECT coalesce(jsonb_agg(jsonb_build_object('rank',rank,'name',frozen_name) ORDER BY rank),'[]'::jsonb) FROM selected WHERE id IS NULL),
 'name_only_fallbacks',(SELECT coalesce(jsonb_agg(jsonb_build_object('rank',rank,'name',frozen_name,'matched_id',id,'stage_source',data_source,'generated',game_generated) ORDER BY rank),'[]'::jsonb) FROM selected WHERE id IS NOT NULL AND data_source<>'ISOLATED-ATP-2025-12-01-CC-BY-NC-SA-4.0'),
 '2025_per_event_ledger_rows',p.per_event_entries,
 'synthetic_reconciliation_rows',p.synthetic_reconciliation_rows,
 'certified',(c.total_top200=200
    AND c.direct_atp_profile_match=200
    AND c.name_only_nonimported=0
    AND c.generated_homonym_risk=0
    AND c.no_name_match=0
    AND c.imported_source_drift=0
    AND c.in_game_rank_mismatch=0
    AND p.per_event_entries>0
    AND p.synthetic_reconciliation_rows=0)
) AS top200_audit
FROM counts c CROSS JOIN provenance p;
